import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getTeamSettingsHandler } from "../handlers/getTeamSettingsHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof getTeamSettingsHandler>>;

export function useGetTeamSettings(
  username: string,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getTeamSettings", username],
    queryFn: () => getTeamSettingsHandler(username),
    ...options,
  });
}
